const NONE: string[] = [];

// Leaf subcategories that also appear in the Jeans & Pants collection.
const JEANS_AND_PANTS_SUBCATEGORIES = new Set(['Jeans', 'Pants']);
// Named items whose trousers are the product itself, even though their leaf is a suit set.
const JEANS_AND_PANTS_PRODUCT_NAMES = new Set(["Women's Tailored Blazer & Trouser Set"]);

// Primary categories whose women's items also belong to Women's Clothing, so the
// Women's Clothing Dresses / Tops / Outerwear navigation shows them by membership.
const WOMENS_CLOTHING_SOURCE_CATEGORIES = new Set(['dresses-and-tops', 'jackets-and-outerwear']);

interface SampleSpec {
  name: string;
  categorySlug: string;
  subcategory: string;
  priceUsd: number;
  colors: string[];
  sizes: string[];
}

function spec(
  name: string,
  categorySlug: string,
  subcategory: string,
  priceUsd: number,
  colors: string[] = NONE,
  sizes: string[] = NONE,
): SampleSpec {
  return { name, categorySlug, subcategory, priceUsd, colors, sizes };
}

